import{c as d,h as e}from"./watch-Ci1HG5Rl.js";const m="data:image/png;base64,",f="data:image/png;base64,",C="data:image/png;base64,",M="data:image/png;base64,",B="data:image/png;base64,",p="data:image/png;base64,",u="data:image/png;base64,",Q="data:image/png;base64,",b="data:image/png;base64,",I=""+new URL("char-readable-CqFBSqQ1.png",import.meta.url).href,E="data:image/png;base64,",D="data:image/png;base64,",z="data:image/png;base64,",Y=""+new URL("grass-bad-good-NBEpj8_H.png",import.meta.url).href,k="data:image/png;base64,",G=""+new URL("group-bad-good-Bt1GbADa.png",import.meta.url).href,v="data:image/png;base64,",y="data:image/png;base64,",Z="data:image/png;base64,",P=""+new URL("pal-series-BAFO3YCn.png",import.meta.url).href,x=""+new URL("pal-spend-DNYSJC20.png",import.meta.url).href,F=""+new URL("pal-swap-D-8vPMQ2.png",import.meta.url).href,O="data:image/png;base64,",T=""+new URL("screen-board-DQ--6Efp.png",import.meta.url).href,L=""+new URL("screen-cartoon-CI0z0VUC.png",import.meta.url).href,N=""+new URL("screen-colors-CYfMpf_H.png",import.meta.url).href,H=""+new URL("screen-signs-5jtbKOWr.png",import.meta.url).href,U=""+new URL("screen-talk-J03kJsQC.png",import.meta.url).href,X=""+new URL("screen-title-81YhtQnz.png",import.meta.url).href,j="data:image/png;base64,",W="data:image/png;base64,",R="data:image/png;base64,",K="data:image/png;base64,",J=""+new URL("shadow-cost-DBz-HTuz.png",import.meta.url).href,V=""+new URL("shadow-direction-CUwRrxqv.png",import.meta.url).href,S="data:image/png;base64,",q="data:image/png;base64,",_="data:image/png;base64,",$="data:image/png;base64,",ee=""+new URL("word-alphabet-BqKrr5zy.png",import.meta.url).href,te="data:image/png;base64,",ae="data:image/png;base64,",oe="data:image/png;base64,",se="data:image/png;base64,",he={id:"characters",no:4,title:"Characters that move",about:"A character in 20 x 20: frames, the four ways it faces and a climb view, a walk cycle, and when to mirror.",starters:["Meet the Monsters","Kit’s Moves"],lessons:[{id:"frames",title:"1. A character is a few pictures in turn",parts:[{p:"Nothing on the screen really moves. A character is a short list of pictures, called frames, and the game shows the next one as the character goes. A character that is standing needs one frame. One that is walking needs a few."},{fig:"char-frames",alt:"A small traveler in a blue cap and green jacket, seen from the front, three times: standing with arms down, then with one foot raised and the arms swung, then with the other foot raised and the arms swung the other way.",caption:"Three frames of one traveler: stand, step, step with the other foot."},{p:"Each frame is a whole 20 x 20 picture, and every frame is the same size, with the feet at the same height. If the feet jump up or down between frames, the character bobs on the ground like a ball."},{ul:["Draw the standing frame first. The others are small changes to it.","Change as little as you can between frames: a leg, an arm, a pixel of head. The eye fills in the rest."]}]},{id:"facings",title:"2. Four ways to face, and a climb view",parts:[{p:"A hero in a game needs to show which way it is going. That takes one picture for each of the four ways it can face: toward you, away from you, to the left and to the right. A ladder or a vine needs one more, a climb view, with the hands reaching up."},{fig:"char-directions",alt:"Five frames of the traveler. First, from the front with a yellow pocket. Second, from the back with a red satchel on a strap. Third, facing right. Fourth, facing left, the same as the third turned around. Fifth, from behind on a wooden ladder with one hand up.",caption:"Front, back, right, left (the right one turned around) and climbing."},{p:"Front and back look alike in outline but are different drawings: the front has a face, the back has a cap and whatever the character carries, such as the satchel here. The side view is the narrowest. Draw the climb view from behind, so that the arms read as holding on."}]},{id:"walk",title:"3. A walk cycle in four frames",parts:[{p:"A walk is a loop. In a side view the loop has four frames: a contact with the front foot out, a passing frame with the legs together, a contact with the other foot out, and another passing frame. Play them in order and begin again."},{fig:"char-walk",alt:"Four frames of the traveler facing right. In the first his legs are wide apart. In the second the legs are together with one lifted a little. In the third the legs are wide apart with the other foot forward. In the fourth the legs are together with the other leg lifted.",caption:"Contact, passing, contact, passing. The arms swing the opposite way to the legs."},{ul:["The arms swing against the legs: when the right foot is forward, the right arm is back.","On the passing frames the lifted foot is one pixel higher. That one pixel is what makes it look like a step.","The head stays at the same height, or dips one pixel on the contact frames. Never more.","Keep the loop at four frames. Eight frames are twice the blocks for a small gain at this size."]}]},{id:"mirror",title:"4. Mirroring, and what it costs",parts:[{p:"The left-facing frames can be the right-facing frames turned around. That saves drawing time, and a side view looks much the same either way."},{fig:"char-mirror",alt:"Four frames of the traveler. The first faces right with a red satchel behind him. The second is its mirror image, facing left, with the satchel behind him on the other side. The third is the traveler from the front with a yellow pocket on the left of his chest. The fourth is its mirror image, with the pocket on the right.",caption:"Left pair: a side view mirrors well. Right pair: a pocket on the chest jumps to the other side."},{p:"It is not free, though. A mirrored frame is a new block in the game, the same as any other, so you save time, not blocks. And anything that sits on one side of the character changes sides: a pocket, a sword at the hip, a stripe on a sleeve, any lettering. The traveler becomes left-handed."},{ul:["Mirror the side views. Draw the front and the back by hand.","Keep marks that matter in the middle (a belt buckle, a badge on a cap), or draw them on both sides.","Never put letters on a character that you plan to mirror."]}]},{id:"readable",title:"5. Keep it readable at 20 x 20",parts:[{p:"Twenty pixels is small, and a player sees the character for a fraction of a second while it moves. Big shapes and strong color differences carry; fine detail turns to noise."},{fig:"char-readable",alt:"Three rows of the five traveler frames. The top row is covered in speckled mixed colors and is hard to read. The middle row is the clean drawing: blue cap, skin, green jacket, brown trousers. The bottom row is solid dark silhouettes of the same frames.",caption:"Top: too busy. Middle: the same shapes, flat colors. Bottom: the silhouettes."},{p:"Try the silhouette test. Fill the whole character with one dark color. If you can still tell the front from the side, which way it faces and what it is doing, the drawing works. If it is a blob, the shape needs fixing before any color will help."},{ul:["Use four or five colors for the whole character, with two or three values in each ramp.","Put the lightest color at the head and the hands, where the eye goes.","Pick colors that stand apart from the ground the character walks on.","The same drawing recolored is a different character: a new cap and jacket make a second foe from the same frames, and the extra blocks are only the recolored copies."]}]}]},ne={id:"animation",no:5,title:"Block animation",about:"Water, torches and doors from a few frames: a block that turns into another, a loop that closes without a jump, and what each frame costs.",starters:["Heat Waves","Switches","Keys and Doors"],lessons:[{id:"ring",title:"1. A block that turns into another",parts:[{p:"A ground block can be told two things: which block to turn into, and how long to wait first. When the wait is over, every place on the map that shows the block shows the next one instead. Give the next block the same two settings and a chain of blocks turns one after another. Point the last one back at the first and the chain is a ring: a loop that runs as long as the scene does."},{p:"The wait is counted in ticks, and a tick is about 55 thousandths of a second (18.2 a second). A frame that waits 4 ticks shows for a bit over a fifth of a second."},{fig:"anim-heat",alt:"Six blocks side by side with an arrow between each pair. Each shows a pale sky above a strip of reddish-brown ground. The ground edge has a small notch at the right end that moves a pixel or two from block to block.",caption:"A ring of six blocks from the Heat Waves Starter, level one, each waiting 4 ticks. The sixth turns back into the first, so the notch keeps moving."},{p:"A ring of six blocks at 4 ticks takes 24 ticks (about 1.3 seconds) to come round. The art of the loop is what changes between neighbors. In the ring above a pixel or two of the edge moves, and the eye reads motion, not a change of picture."},{ul:["Only ground blocks animate this way. Monsters and the hero animate by frame lists, which is course 4.","The first block in the ring is the one the map holds. Start the ring where you want a level to open.","A block that never changes has no next block (or itself as its next block) and a wait of 0."]}]},{id:"water",title:"2. Water that closes its loop",parts:[{p:"A loop only looks smooth if its last frame leads into its first. The easiest way to get that is to move something by the same step each frame and make the steps add up to a whole repeat. A wave with a repeat of 20 pixels, moved 5 pixels a frame, is back where it began after four frames."},{fig:"anim-water",alt:"Top: four blocks of blue water with a wave crest and a white glint on top, the crest moving a quarter of a wave to the right in each block. Bottom: six water blocks in a row, in the order one, two, three, four, one, two, forming a continuous rolling wave with no join between blocks.",caption:"Top: four frames, each 5 pixels further along. Bottom: the frames laid in a row, then the ring starting again. The wave runs on across every join."},{p:"The same rule makes water tile. The wave goes up and down by the same amount at the left and right edges of the block, so a row of water blocks is one long wave. Move the whole block by whole pixels and every frame keeps that edge."},{ul:["Pick a repeat that divides 20: 5, 10 or 20 pixels. Then 4, 2 or 1 frames close the loop.","Keep the colors the same and move the shapes. Water that changes color from frame to frame flickers.","A white glint on a crest is the cheapest way to say that the surface is wet."]}]},{id:"fire",title:"3. Fire and torches",parts:[{p:"Fire is the opposite of water. It does not travel, it flickers: the flame leans, grows and shrinks in place while the torch under it stays still. Draw the torch once. Draw the flame four times, each a little taller or leaning another way, on the same torch."},{fig:"anim-torch",alt:"Four blocks, each a stone wall with a wooden torch on it and a flame. The flame is red at the edge, yellow inside and white at the heart. In the four blocks it is a different height and leans a little left, straight or right.",caption:"Four frames of one torch. The bracket and the wall are the same in all of them; only the flame changes."},{p:"Flames also want an uneven beat. A ring where every frame waits the same time ticks like a clock, and a flame that ticks is not a flame. Give one frame a longer wait, or waits of 2 and 3 ticks mixed. The cost is the same four blocks."},{ul:["Everything that is not fire stays pixel for pixel the same, so that only the flame moves.","Use three or four colors in the flame: an outline, a body, a bright heart. A fifth color rarely shows.","A flame that moves a lot looks lively but costs attention. In a corridor of torches, keep them small."]}]},{id:"touch",title:"4. Doors and levers: change once, when touched",parts:[{p:"A block can also turn into another when the hero touches it. That is not a loop. It happens once, and the new block stays for the rest of the visit to the scene. It is how a shut door becomes open air and a lever stays flipped."},{fig:"anim-door",alt:"A wooden door with a gold padlock on the left, an arrow, and on the right a plain light blue block of sky.",caption:"The door block of the Keys and Doors Starter: solid on every side, it spends one from a counter (a key), and when touched it turns into block 0, plain sky."},{fig:"anim-lever",alt:"A gray lever box with a red knob on a stick, an arrow, and the same box with the stick flipped and a yellow knob.",caption:"A lever of the Switches Starter and the block it turns into when touched. It adds planks to a counter as it flips."},{p:"A block like that needs two pictures, before and after, and each is a block. The swap only happens when the cell is on the screen, so keep a lever or a door where the hero will see it change."},{ul:["Draw the after picture so it still fits the picture around it: an open door is the doorway behind it.","Leave a hint in the picture of what the block will do: a lock on a door, a knob on a lever.","Make the change easy to see. A door that opens is not a hard thing to miss; a lever that shifts one pixel is."]}]},{id:"cost",title:"5. Timing, and what each frame costs",parts:[{p:"Every frame is a block, and a game has 150 of them for its whole ground. A ring of four frames takes four of the 150. Count it as you drew it: a four-frame torch, a four-frame water, and the doors and levers with their after pictures are already a dozen blocks before any plain ground."},{p:"In the CD’s games and the Library (not counting the Starters) there are 1,537 closed rings in 210 block files. Two frames is by far the most common, 999 of them; then four (218) and three (197). Rings of five frames or more are rare: 123 in all."},{fig:"anim-stagger",alt:"Two rows of six wall torches. In the top row every torch has the same flame. In the bottom row the flames are different heights and lean different ways, as if each flickered on its own.",caption:"The same four torch blocks. Top: every cell uses the first block, so all flames move together. Bottom: different cells use different blocks of the ring."},{p:"Every cell that uses the same block changes on the same tick, so a row of torches made from one block flickers in step. The cure costs nothing. A ring has as many members as frames, and any member can be put in the map. Put member 1 in one place, member 3 in the next and member 2 after that, and the flames are out of step with only the same four blocks. For water, keep them in step, so that the wave stays one wave."},{ul:["The wait for each frame counts from the end of the last one, so a ring does not drift out of time.","A changed block is redrawn as one of at most 170 screen boxes, which monsters and the hero use too (the Guide’s chapter 5 counts it, and has not tried it in DOSBox). A few torches and a pool will not run out; a screen full of animation and a crowd of monsters might.","Two rings may not share a block. A block has only one next block.","Give a ring waits of 2 to 6 ticks for most things. Longer is for a slow pulse; 1 tick is the fastest."]}]}]},Ae={id:"palettes",no:3,title:"Palettes",about:"Colors in a ramp, one palette to a scene, how a game spends its 256 colors, and one set of blocks given a new look.",starters:["Colors That Work","Day and Night"],lessons:[{id:"ramps",title:"1. A ramp is a color family, dark to light",parts:[{p:"A scene has 256 colors to spend, so the first habit is to spend them in families. A ramp is one color in a few steps from dark to light: four or five greens, three or four browns. A pixel that is lit takes a light step, a pixel in shade takes a dark one, and the picture gets its shape from the steps and not from outlines."},{fig:"pal-ramps",alt:"Six rows of colored squares. Row one is five greens, from dark forest green to bright lime. Row two is four browns. Row three is four grays. Row four is four tans. Row five is three reds. Row six is three blues. Each row goes from dark on the left to light on the right.",caption:"The ramps behind these courses: grass, soil, stone, wood, roof and water. Dark on the left, light on the right."},{p:"The number of steps is the budget. One step makes a flat disc, two make a disc with a shadow, and four make something round. More steps than that cost colors without the eye noticing."},{fig:"pal-balls",alt:"Two rows of three balls on a blue sky. The top row is brown, the bottom row is green. In each row the left ball is one flat color, the middle ball has two shades with a light patch and a dark crescent, and the right ball has four shades and looks round.",caption:"One, two and four steps of the same ramp. Four steps (right) read as a ball; the flat ones (left) are a disc."},{ul:["Give each family its own run of palette numbers, in order from dark to light. A ramp you can find again is a ramp you can edit.","Three to five steps is plenty for 20 x 20 blocks.","Reuse a ramp for more than one thing. Grass, a hedge and a leaf can share greens."]}]},{id:"hue",title:"2. Shades that lean",parts:[{p:"The simplest ramp keeps the hue and changes only the brightness. It works, and it tends to look flat and muddy. Painters have long let shade lean cool and light lean warm: the dark steps drift toward blue or purple, the light steps toward yellow. The picture gets a mood for the price of choosing the steps with a little more care."},{fig:"pal-hue",alt:"Two copies of a small tan house with a dark roof and a door on a blue sky, each with its five-color ramp as squares below. In the left house the shades are all the same brown-tan, just darker and lighter. In the right house the dark steps lean purple and the light steps lean yellow.",caption:"The same house and the same five steps. Left: only brightness changes. Right: the dark steps lean purple and the light ones lean yellow."},{p:"Each color is three numbers from 0 to 63 for red, green and blue (six bits each), so a lean is a small change: raise the blue of a dark step, raise the red and green of a light one. The edit costs nothing, because it is the same five palette entries either way."},{ul:["Pick the middle step first, then lean the ends away from it.","Lean the same way in every ramp of a scene, or two ramps will look lit by different lamps.","Keep a few steps that do not lean: skin, a white, a black. A lean on every color of a scene is a tint."]}]},{id:"scene",title:"3. One palette to a scene, and who shares it",parts:[{p:"A scene names one palette (file slot 0 of the scene). Its ground blocks, its monsters and its hero are all drawn with the same 256 colors, because there is only one set of colors on the screen at a time. The Programmer’s Guide gives the sources (PLAYGAME line 4244, chapter 11); here it is a drawing rule: every picture in a scene has to be drawn from the same palette."},{p:"That makes the palette a shared pantry. The first level of Pass the Pie, the yard, uses 80 of its 255 usable colors. The ground blocks use 53 of them, the monsters 37 and the hero 33, and some are the same entries in two places: blocks and monsters share 27, blocks and hero 16, monsters and hero 12."},{fig:"pal-spend",alt:"Three grids of 16 by 16 squares, labeled BLOCKS, MONSTERS and HERO. Each grid shows the same 256 palette entries, and only the entries that group uses are colored; the rest are dark gray. The block grid has the most colored squares, in oranges, creams, reds and a few greens and blues. The monster grid has oranges, browns and purples. The hero grid has browns, golds, greens and a blue.",caption:"Pass the Pie, level one: the same 256 palette entries three times. Colored means the group paints with it."},{p:"Sharing is fine for the colors that belong to everything: an outline, a white, a skin tone. A color that a hero needs to stand out against the ground is another matter. A hero in the same greens as the grass vanishes when it walks over it, and a monster in the ground’s browns looks like a bump. In the yard, 17 of the hero’s 33 colors are used by no ground block, which is why the hero reads on any of them."},{ul:["Draw the ground first, then pick the hero’s and the foes’ main colors from outside the ground’s ramps.","Color 255 is the clear color in a hero or monster, so only 255 colors are left for them (Guide chapter 11). In a ground block, 255 is an ordinary color.","Leave a clear blue, a red and a yellow in the palette. The inventory screen and the error boxes ask for those and take the nearest color the scene has (Guide chapter 11, PLAYGAME lines 287 to 290)."]}]},{id:"series",title:"4. How the games spend their 256 colors",parts:[{p:"Here is what a scene of each kind of game actually paints with. These come from reading every game on the Sample CD and in the Library: for each scene, how many different colors its ground, monster and hero block sets use together (a set counts all of its blocks, whether or not the map uses them)."},{fig:"pal-series",alt:"A bar chart. Six bars of green, longest first, each labeled and numbered: gameware 160, shareware 112, bizarre 111, sandbox 106, special 84 and starters 78. A pink line marks the 256 colors a palette holds, at the far right.",caption:"Average colors used by a scene’s block sets. The pink line is the 256 a palette holds, and no scene comes near filling it on average."},{ul:["The Gameware games on the CD are the most colorful: 160 colors on average, and up to 227 in one scene. They also keep one palette for the whole game in 13 of 17 cases, which is how they stay under 256.","The Shareware games average 112 and have one palette in 8 of 12 games.","The retail Sandbox games and the Bizarre games sit near 110. They give most scenes a palette of their own, 13 per game on average in the Sandbox games (one game has 99), and 5 per game in the Bizarre ones.","The specials average 84, with one palette per scene: 6 palettes for 6 levels in Pass the Pie.","The Starters need only 78. They teach one idea each, in a few colors."]},{p:"Two lessons come out of the numbers. A big palette is for a game that keeps it for every scene. A game with a new look in every scene can only afford a small one, because each scene’s hero, foes and ground are all counted again. If every scene needs 150 colors, the scenes will look alike or the blocks will have to be redrawn for each."}]},{id:"swap",title:"5. A new look from the same blocks",parts:[{p:"A palette swap gives a block set a new look without touching a pixel. The blocks and the map stay as they are, only the 256 entries change, and the same scene is day, then night."},{fig:"pal-swap",alt:"Two copies of the same living room scene side by side. On the left it is day: pale green wallpaper with white daisies, a window with blue sky, brown wood paneling and an orange sofa with a person sitting on it. On the right it is night: the same wallpaper and sofa in dark blue and brown, with a dark window and stars.",caption:"One screen of A Fly Named Carl, drawn with its couch palette (left) and its bed palette (right). The map and the blocks are the same."},{p:"A Fly Named Carl draws its house with one set of blocks under four palettes (couch, walls, bed and a cord scene), and the first palette and the last agree on only 152 of their 256 entries. Third Goat from the Left does the same with a field, a town, a caravan and a stable. It is common in the Bizarre games: 11 of the 12 do it, so a four-level game costs one set of blocks and four small palette files."},{p:"The same trick can be used for a whole run of scenes. Pass the Pie has six levels, each with its own palette, and every one of them keeps the same hero and monster sets, so its first and last palettes agree on 238 of 256 entries. The hero looks like the hero in every level while the ground changes."},{ul:["Draw with ramps and the swap is easy: change the five entries of a ramp and everything that uses it changes together.","Swap the colors a scene is made of and leave the hero’s alone, or the hero changes too.","Make the night darker and bluer, and keep a clear light (a window, a lamp) at a bright index, so the scene still has something to read by.","The Day and Night Starter has one map and two looks, and is the quickest way to try it."]}]}]},re={id:"screens",no:7,title:"Screens with words: titles, cartoons and talk",about:"The screens between the levels: a title picture with room for the game’s words, a cartoon of a few held poses, signs that fit and talk that sounds like somebody.",starters:["Make a Title","Pictures and Cartoons","Everybody Talks"],lessons:[{id:"title",title:"1. A title picture leaves room for words",parts:[{p:"A title screen is one picture, 320 pixels wide and 200 tall, drawn once and shown whole. It is the first thing a player sees, so it gets the biggest drawing in the game: the hero, a stage, the game’s name in letters bigger than any in the levels."},{fig:"screen-title",alt:"The title picture of Make a Title: red stage curtains on both sides, the words MAKE A TITLE in yellow letters across the top under a row of lights, a hero in a blue beanie and red jacket standing on the stage, a framed picture and a computer screen behind him, and the word COURSE and a number lettered on the floor.",caption:"A title picture: a big hero, a stage, the name across the top."},{p:"But the picture is not the whole screen. The menu is lettered on top of it by the game, in the same 8 x 8 letters as the rest of the text. That means the picture has to leave the board under the menu plain, with no detail that the words would cross."},{fig:"screen-board",alt:"A blueprint-style template of the menu picture, with a ruler along the top and left. Hatched boxes mark where the game writes: a red strip for a missing page, a blue strip for the game’s name, a column for the marker, and six choices (Play, Read Instructions, Read Storyline, See Credits, See Highest Scores, Quit) in a blue box.",caption:"The template that comes with the Starter. The game writes in the hatched boxes, so the picture draws around them."},{ul:["Find the boxes first, then draw. Put the big art where the words are not.","Draw the words’ area as a calm, flat color, or a quiet pattern: a board, a banner, a stage floor.","Never put the menu words on a busy spot, such as a face or fine stripes. The letters are one color, and they will be lost."]}]},{id:"colors",title:"2. A few colors, chosen on purpose",parts:[{p:"The screen shows at most 256 colors at a time, and a picture can ask for fewer. A title that uses most of them will look rich for the first minute and muddy next to the next picture, so a title is built from ramps: a few colors in each family, from dark to light."},{fig:"screen-colors",alt:"The Make a Title picture again, with a gray panel beside it holding a grid of small squares, each a color used in the picture: dark blues and blacks, a column of light blues, browns, golds, yellows, reds, purples and pinks, and a few grays.",caption:"The same title and, beside it, every color it uses: 52."},{ul:["Count your ramps rather than your colors. Here there are a handful of families, each with a few steps.","A color that appears once is a color to look at again. Cut it, or fold it into a neighbor.","Dithering, the speckled blend of two colors, is cheap in colors and busy to look at. Use it on backdrops, never behind the words."]}]},{id:"cartoons",title:"3. A cartoon is a few held poses",parts:[{p:"A cartoon is a file of full-screen frames, played once between two levels. It has no sound, and PLAYGAME plays all of it before it looks for a key. Each frame waits a fixed time before the next. The one below has 40 frames at a sixth of a second each, about three seconds and a half."},{fig:"screen-cartoon",alt:"Six frames of a cartoon, two rows of three. A traveler in a pink beanie stands beside a mound of soil with a seed. A sprout grows in the second frame, taller in the third, tall with a bud in the fourth. In the fifth a white daisy has opened and the word BLOOM! is lettered across the top, and in the sixth the traveler has arms down and the daisy is bigger.",caption:"Frames 0, 10, 20, 30, 33 and 39 of a 40-frame cartoon."},{ul:["Change one thing at a time. The hero stands still, and only the plant grows. A frame that changes a little costs a few bytes; a whole new picture costs the screen.","Draw the backdrop in flat bands, not dither. The cartoon above is about 36 KB for 40 frames. Dithered sky would have made every frame large.","Hold the pose that matters. The flower is open for the last seven frames, and the eye reads it as the end.","Let a caption carry the joke. Pictures can say what happens, but a word such as BLOOM! says how to feel about it, and it appears with the last pose so that it is read while the picture is still."]},{p:"Pick a spot for the caption as you plan the frames, and keep it plain, as in the first lesson. The letters are the biggest on the screen, with a dark outline so that they read against any sky."}]},{id:"signs",title:"4. A sign has only so much room",parts:[{p:"A sign is a few blocks wide with words lettered on it in the same 8 x 8 font. The letters do not shrink to fit, so the board decides how much can be said. A board of three blocks holds six letters across, and four blocks hold nine. A board one block high holds one line, and two blocks hold four."},{fig:"screen-signs",alt:"Four wooden signs on two posts each. In the first row, EXIT on a short board, WATCH OUT on a board a little wider, and a bigger board with MIND THE on one line and GAP on a second. Below, a board with MIND THE GAP on a single line that is longer than the board: the M and the P stick out on the sky on each side.",caption:"Three signs that fit, and one, below, where the words are wider than the board."},{ul:["Count the letters. Each is 8 pixels, and a space is one too.","Break lines at spaces, so a word never splits in two. MIND THE and GAP is better than MIND THE G and AP.","A word that is too long for the board needs a wider board. It cannot be broken.","Say it in as few words as you can. The player is walking past."]}]},{id:"talk",title:"5. Talk: lines that fit, a voice for each",parts:[{p:"Talk is a picture with the words laid over it. PLAYGAME writes a text file over the picture in rows of 8 pixels, starting 40 pixels in from the left and 40 down, one color for all of it, and sixteen rows at most. So the picture draws the bubbles and the names, and the text file holds only what is said."},{fig:"screen-talk",alt:"A picture of a meadow and hills with four people standing in a column at the right edge. Three speech boxes sit across the screen. PIP says: Moss! Dot! Look who it is. MOSS says: Kit! Just in time. Dot has a riddle. DOT says: What has a lid and a spout, and never goes anywhere?",caption:"A talk card: bubbles and names are in the picture, the words in the bubbles come from a text file."},{ul:["Fit the bubble. Here a line holds 28 letters, and a turn holds the rows between its name and the next. A long turn runs to a second card.","Break lines at the places a person pauses: at a comma, or before a long word.","Give each character one voice and keep it. Pip is quick and says very little. Moss is steady and explains. Dot asks the riddles. Cover the names with your hand: if you can still tell who is talking, the voices are right.","Short turns, and plenty of them. A talk of two long speeches is not a talk."]},{p:"Keep the words and the picture in step. If the bubble is a color and a mood, the person speaking should sound like that. A bubble the same shape for everyone makes everyone sound the same."}]}]},ie={id:"shadows",no:2,title:"Shadows and depth",about:"A shadow under a bridge or a building, solid or dithered, drawn once and reused along an edge, with the light always from one side.",starters:["Little Shadows","Near and Far"],lessons:[{id:"step",title:"1. A shadow is the ground, one step darker",parts:[{p:"A bridge with nothing under it looks like it is floating a little. The cure is cheap: the ground under the deck gets darker. A shadow is not a new color to invent. It is the same ground, one or two steps further down its own color ramp."},{fig:"shadow-bridge",alt:"Two copies of a wooden bridge with rails over a green lawn. In the left one the lawn under the deck is plain. In the right one a dark green band lies on the lawn under the deck, and the bridge sits on the ground.",caption:"Left: a deck over plain grass. Right: the grass under it is two steps darker."},{p:"Take each grass pixel and swap it for the darker one in the same ramp. The speckle stays, so the shadow still looks like grass, only in the dark. A shadow of flat black would look like a hole."},{ul:["Keep the shadow in the same hue as the ground. A hint toward blue or green is fine, a gray patch is not.","Make it a few pixels tall. The ground under a deck only needs a band to say that the deck is above it."]}]},{id:"dither",title:"2. Solid, or dithered",parts:[{p:"There are two ways to fill a shadow. Solid means every pixel takes the darker color. Dithered means every other pixel does, in a checkerboard, and the eye mixes the two colors into a shade in between."},{fig:"shadow-solid-dither",alt:"Three strips of five grass blocks, each with a dark band along the top. The first band is solid dark green. The second is a fine checkerboard of dark and normal green. The third is solid at the top with a two-pixel checkerboard fringe under it.",caption:"Top to bottom: solid, dithered, and a solid core with a dithered fringe."},{p:"Solid is crisp and reads from far away. Dithered is lighter, which suits a soft shade or a light that is far off, but it adds a texture of its own, and next to grass speckle it can look like noise. A solid core with a short dithered fringe is a good middle: a firm shadow with a soft edge."},{p:"Whichever you pick, use it for every shadow in the level. Two kinds of shadow on one screen look like two different lights."}]},{id:"edge",title:"3. One shadow block, used along an edge",parts:[{p:"A wall or a bridge has a long edge, and the shadow under it is a long strip. Do not draw that strip. Draw one block of it and place the block again and again, the same way as a block of plain ground."},{fig:"shadow-edge-set",alt:"Three grass blocks side by side: a plain one, one with a dark band along its top, and one with the dark band only in its top left corner.",caption:"The whole kit: plain ground, a band, and a band that stops after six pixels."},{fig:"shadow-wall",alt:"Two copies of a stone wall with a red roof beside it. In the left one the grass at the foot of the wall is plain. In the right one a dark band runs along the foot of the wall, past its right end by a few pixels.",caption:"The band goes under every block of the wall. The end block takes the shadow a little past the corner."},{p:"The band is drawn so that its left and right edges meet, as in lesson 2 of the first course, so any number of them make one unbroken strip. The end block is the same band cut short. With the light on the left, the shadow runs out a little past the right-hand end of the wall, and one end block covers that."}]},{id:"light",title:"4. The light comes from one place",parts:[{p:"Pick a direction for the light and keep it. If the sun is up and to the left, every shadow in the level falls down and to the right. This matters more than how well the shadow is drawn: a perfect shadow on the wrong side makes the whole picture feel odd, and a player will notice before they can say why."},{fig:"shadow-direction",alt:"Two scenes of two small houses with a yellow sun in the upper left corner. In the left scene each house has its dark shadow on the grass to its right. In the right scene the first house has its shadow on its right and the second house has its shadow on its left.",caption:"Left: one sun, both shadows fall right. Right: the second house has a shadow on the sunny side."},{ul:["Decide the direction once, before drawing any shadow, and write it on a note by your screen.","A shadow on the left of one thing and the right of another is the common slip. Check every pair.","Highlights go on the side facing the light and darker colors on the other side, by the same rule."]}]},{id:"cost",title:"5. How few blocks a shadow costs",parts:[{p:"Blocks are limited, so count. A shadow made as lesson 3 describes costs only the blocks of the kit, however long the wall is."},{fig:"shadow-cost",alt:"Two copies of a stone hut with a red roof and a door, on a lawn. The left one has no shadow. The right one has a dark band at its foot.",caption:"The same hut. Without a shadow it takes 5 blocks. With one it takes 7."},{p:"The hut has sky, roof, wall, door and grass, which is 5 blocks. Its shadow adds two: the band and the band cut short. That is the whole price, and a wall twice as long would still cost 7. Two blocks is a small price for one of the most noticeable changes in a picture."},{p:"Be careful where the shadow crosses detail. A band that lies over ground with a tuft or a flower needs its own copy of that block, so keep the ground under a shadow plain. The plain ground the shadow does not touch stays as it was."}]}]},le={id:"words",no:6,title:"Words as monsters",about:"A foe made of letters: why a word turns backwards when it walks the other way, which letters survive it, and how to draw around it.",starters:["Meet the Monsters","Everybody Talks"],lessons:[{id:"backwards",title:"1. Why a word reads backwards",parts:[{p:"A monster is one 20 x 20 block, drawn with its feet on the ground. When a monster that chases the hero walks to the left, PLAYGAME draws the same block turned around, left for right. It does this for every monster that chases or runs away, and it does it to the whole block, letters and all."},{fig:"word-flip",alt:"Four word monsters, each a blue plate with yellow letters and two feet. The first says NO. The second is the first turned around: the O is on the left and the N is a backwards N. The third says GO. The fourth is turned around: the O is on the left and the G is backwards.",caption:"NO and GO as drawn, each with the picture the game shows when it walks to the left."},{p:"Turning a block around does two things at once. The letters swap places, so the word runs the wrong way, and each letter is itself drawn the wrong way. N becomes a backwards N and G a backwards G. That is not a word anymore, it is a puzzle."},{ul:["The turn happens in the game, not in your picture. There is no copy of the block in the file for the left.","A monster that follows a path is different: you choose, for each leg of the path, whether its picture is turned. Leave every leg unturned and the word never flips.","A monster that wanders from place to place is not turned by the movement code.","A block the hero fires can also be turned on its side, to go up or down. A word on one would be sideways."]}]},{id:"letters",title:"2. The letters that turn around cleanly",parts:[{p:"Some letters look the same turned around. In the game’s 8 x 8 font, drawn in code here, these eleven do: A, H, I, M, O, T, U, V, W, X and Y. The digit 8 does too. Every other letter changes."},{fig:"word-alphabet",alt:"The alphabet in two halves, A to M above and N to Z below. Each letter is shown twice, in a row of its own and in a row turned around beneath it. A, H, I, M, O, T, U, V, W, X and Y are on a green background and look the same turned around. The other letters are on dark red and look different.",caption:"Each letter, and the same letter turned around. Green: no change. Dark red: it changes."},{p:"Use the green letters for a word that has to read both ways, and keep the dark red ones for a monster that never turns."}]},{id:"pairs",title:"3. Make the turn part of the joke",parts:[{p:"Since a turned word runs backwards, pick words that are still words backwards. Made only of green letters, AH turned around says HA, and OH says HO. A monster that sighs one way and laughs the other is a better monster than one that only says one thing."},{fig:"word-pairs",alt:"Three word monsters, each shown as drawn and turned around. AH becomes HA. OH becomes HO. AHA, three letters across the whole block in dark letters, looks the same turned around.",caption:"AH and HA, OH and HO, and AHA, which is the same both ways."},{p:"A word that is the same turned around is a palindrome, and with green letters it works at any size that fits. AHA is exactly 20 pixels across, with a pixel between the letters. HAH and TAT fit the same way."},{ul:["Words that survive in one block: AHA, HAH and TAT.","Words that turn into other words: AH and HA, OH and HO, TO and OT.","When it matters which way the word reads, draw it for the way the monster goes most. It will read right then and backwards for the rest."]}]},{id:"two-blocks",title:"4. A word across two monsters",parts:[{p:"A word wider than one block has to be two monsters side by side. Each is its own block and each turns by itself, where it stands. The two do not trade places."},{fig:"word-two-blocks",alt:"Above, a blue plate across two blocks with the word TOOT, which reads the same both ways. Below, the same two blocks each turned around where it stands: the left block shows OT and the right block shows TO, so the plate reads OT TO.",caption:"Top: TOOT across two blocks. Bottom: each block turned in place. The halves did not swap."},{p:"TOOT is the same forward and backward, so you would think it is safe. It is not, because the halves stay where they are. The left block, TO, turns into OT, and the right block, OT, turns into TO. The word on the screen is OTTO."},{ul:["Give a word of two blocks to monsters that never turn: a path with every leg unturned, or monsters that wander.","Or make each half a palindrome on its own, such as a block that holds AHA.","If the two monsters must move together, give them the same path so that they stay side by side."]}]},{id:"readable",title:"5. Keep a word readable as a monster",parts:[{p:"A word is flat, and a monster has to look like it could walk up to you. Letters in the 8 x 8 font are about 7 pixels across, so two fit in a block with room to spare, and three fit only when they are narrow, with a pixel between."},{fig:"word-readable",alt:"Five word monsters. The first is faint: gray letters on the sky, hard to read. The second and third say AH on a blue plate in bright yellow, with two feet, the feet swapped between them. The fourth says AHA in dark letters straight onto the sky with feet. The fifth says OH the same way.",caption:"Faint and flat, then a plate and feet in two frames, then letters with no plate."},{ul:["Letters need strong contrast with the ground behind them. Light on a dark plate, or dark on light, never gray on sky.","A plate under the word, with a darker row along the bottom, makes it a body. Without it the word is just text that slides.","Feet give the walk. Swap which foot is raised between two frames and the monster steps. A monster can have up to 20 frames, but two are plenty.","Two letters to a block, three only if they fit in 20 pixels. A longer word is two monsters, and the last lesson’s rules apply.","Letters you could not read in the silhouette test of course 4 are letters that will not read on the move."]}]}]},n="Art courses",h=[{id:"blocks",no:1,title:"Blocks: cut, repeat, reuse",about:"Cut a picture into 20 x 20 blocks, make edges that meet, reuse one block many times and keep grass from showing a pattern.",starters:["150 Blocks","Little Shadows"],lessons:[{id:"cut",title:"1. Draw big, then cut",parts:[{p:"Every picture in a level is made of blocks, and every block is 20 pixels wide and 20 pixels tall. A house is not one block. It is a few of them side by side, like tiles on a floor."},{p:"The easy way to draw one is to draw it whole. Make the canvas a multiple of 20 (here 60 x 40, which is three blocks by two), draw the house, then cut the canvas along a 20-pixel grid. Each square becomes one block, and the map puts them back in the same order."},{fig:"cut-whole",alt:"Two copies of a small brown house with a red roof on a green lawn. The second has pink lines cutting it into three squares across and two down.",caption:"The same 60 x 40 picture, whole, and with the 20-pixel cuts marked in pink."},{fig:"cut-apart",alt:"The six pieces of the house picture, pulled apart with a gap between each one.",caption:"Six blocks. Nothing is lost: put them back together and it is the same house."},{p:"Plan the cuts before you draw. Keep a window or a door from straddling a cut when you can, and let the roof line cross it only where you do not mind. Cuts that fall in plain wall are easy to reuse later."}]},{id:"seams",title:"2. Edges that meet",parts:[{p:"A ground block gets placed over and over, so its left edge sits against its own right edge. If you draw a light line along the top and left and a dark line along the bottom and right (a bevel), every block gets its own frame, and a field of them becomes a grid of lines."},{fig:"seam-bad-good",alt:"Two fields of grass, five blocks wide and three high. The left field has a visible grid of light and dark lines at every block edge. The right field is one even stretch of grass.",caption:"Left: a bevel on every block. Right: the same texture with no edge work."},{p:"A block that tiles has no edge of its own. The texture is just the same kind of speckle all the way to the border. The test is simple: put the block next to a copy of itself and look for the join. If you can find it, the block does not tile yet."},{ul:["Draw texture with no pattern that stops at the border: speckles, not outlines.","If a detail touches an edge, draw its other half on the opposite edge so they join when blocks sit side by side.","Keep the average color the same all over the block. A block that is darker at the bottom will stripe."]}]},{id:"groups",title:"3. Groups that fit: 2 x 2 and bigger",parts:[{p:"A stone wall with bricks bigger than 10 pixels does not fit in one block, so draw it as a group, such as 2 x 2 blocks (40 x 40 pixels). The edges of the group have to meet the edges of the next group in the same way a single tile does."},{fig:"group-bad-good",alt:"Left: a stone wall made of four-by-three little squares, each with a dark frame, so it reads as a grid. Right: a stone wall with bricks in a running bond that goes on without any frame.",caption:"Left: each block framed as if it stood alone. Right: one 40 x 40 wall, cut into four, with mortar lines that continue over the cuts."},{p:"The rule is to make the pattern repeat inside the group size. In the wall on the right the courses are 10 pixels tall and the joints come every 20 pixels, so a cut at 20 or 40 pixels lands on a joint, and a group set beside another looks like more of the same wall."},{ul:["Choose a repeat that divides the block: 5, 10 or 20 pixels fit one block; 40 fits a 2 x 2 group.","Draw the whole group first, then cut. Do not decorate the blocks one at a time.","Save the frame (a dark outline or a highlight) for the blocks at the outside of a picture, such as a doorway or a window."]}]},{id:"reuse",title:"4. Use a block again",parts:[{p:"A game gets 150 blocks. A block you place twenty times still counts once, so the cheapest picture is one built from a few blocks repeated. The Programmer’s Guide explains where the limit comes from; here it is a drawing rule: ask of every new block whether an old one would do."},{fig:"reuse-four",alt:"Four blocks of stone wall in a row: the original, a mirrored copy, a blue copy, and a copy shifted sideways by half a block.",caption:"One drawing, four blocks: the original, mirrored, recolored, and slid half a block sideways."},{p:"Be honest about the count. Mirroring, recoloring or shifting a block makes a new block that happens to take little time to draw. It does not make a block free. A block is free only when you place the very same one again."},{fig:"sign-two-and-one",alt:"Two signboards on posts, side by side. On the left the posts are at the far ends and slightly off center. On the right the posts are centered in their blocks.",caption:"Left: a left post and a right post, two blocks. Right: one post drawn in the middle of its block, used at both ends."},{p:"Signs show the idea well. If the post is drawn off to one side you need a left post and a right post. If it is drawn in the middle of its block, one block serves both ends, and the board in the middle is a block you repeat for as long as the sign needs to be. Think of a kit of parts: a post, a board, a corner, a cap. Draw symmetric parts and you can build many things from them."}]},{id:"variants",title:"5. Variants, so the ground does not pattern",parts:[{p:"A player’s eyes find repeats quickly. One grass block with a tuft in the same place makes a lattice of tufts across the whole screen, and the player sees the lattice instead of the game. The cure is a few variants of the same block."},{fig:"grass-bad-good",alt:"Two fields of grass, eight blocks wide and five high. In the left field a small dark tuft repeats in the same spot of every block, forming a grid of dots. In the right field the tufts and one flower are rare and scattered, and the grass reads as one even meadow.",caption:"Left: one block repeated. Right: five blocks used with rules."},{fig:"grass-set",alt:"Five blocks of grass side by side: two plain ones, two with a single tuft in different places, and one with a tiny yellow flower.",caption:"The whole set: two plain blocks, two tufts, one flower. Five blocks, not fifty."},{ul:["Make most of the variants plain. The plain ones carry the field, and the details are the sprinkle on top.","Give the details different places in their blocks, so two of them side by side do not line up.","Never put two detail blocks next to each other. A crowded spot becomes the new pattern.","Two or three plain blocks with different speckle are better than one. It costs two blocks and breaks the repeat more than any tuft."]},{p:"The same trick works for dirt with stones, water with a glint, a path with pebbles and a wall with a crack. A handful of blocks per surface, used with a light hand, is much cheaper than drawing a larger picture."}]}]},ie,Ae,he,ne,le,re],ge=a=>h.find(t=>t.id===a),i=[],A="#/art-courses",we=Object.assign({"./figures/anim-door.png":m,"./figures/anim-heat.png":f,"./figures/anim-lever.png":C,"./figures/anim-stagger.png":M,"./figures/anim-torch.png":B,"./figures/anim-water.png":p,"./figures/char-directions.png":u,"./figures/char-frames.png":Q,"./figures/char-mirror.png":b,"./figures/char-readable.png":I,"./figures/char-walk.png":E,"./figures/cut-apart.png":D,"./figures/cut-whole.png":z,"./figures/grass-bad-good.png":Y,"./figures/grass-set.png":k,"./figures/group-bad-good.png":G,"./figures/pal-balls.png":v,"./figures/pal-hue.png":y,"./figures/pal-ramps.png":Z,"./figures/pal-series.png":P,"./figures/pal-spend.png":x,"./figures/pal-swap.png":F,"./figures/reuse-four.png":O,"./figures/screen-board.png":T,"./figures/screen-cartoon.png":L,"./figures/screen-colors.png":N,"./figures/screen-signs.png":H,"./figures/screen-talk.png":U,"./figures/screen-title.png":X,"./figures/seam-bad-good.png":j,"./figures/seam-block-bad.png":W,"./figures/seam-block-good.png":R,"./figures/shadow-bridge.png":K,"./figures/shadow-cost.png":J,"./figures/shadow-direction.png":V,"./figures/shadow-edge-set.png":S,"./figures/shadow-solid-dither.png":q,"./figures/shadow-wall.png":_,"./figures/sign-two-and-one.png":$,"./figures/word-alphabet.png":ee,"./figures/word-flip.png":te,"./figures/word-pairs.png":ae,"./figures/word-readable.png":oe,"./figures/word-two-blocks.png":se}),ce=a=>{if("p"in a)return e("p",null,a.p);if("ul"in a)return e("ul",null,...a.ul.map(o=>e("li",null,o)));const t=we[`./figures/${a.fig}.png`];return e("figure",null,e("img",{src:t,alt:a.alt,loading:"lazy"}),e("figcaption",null,a.caption))};function de(a){a.append(e("main",{class:"ac-page"},e("p",null,e("a",{href:"#/library"},"← Library")),e("h1",null,n),e("p",null,"How to draw the art for a Game-Maker game. Every picture here is real: blocks drawn in code the way the games’ own art is, or screens, palettes and blocks read from the games themselves, so what you see is what a game spends. Each course points to the Starters on the Sample CD that show the editor side."),e("ul",{class:"ac-list"},...h.map(t=>e("li",null,e("a",{href:`${A}/${t.id}`},e("strong",null,t.title),e("span",{class:"ac-about"},t.about))))),...i.length?[e("h2",null,"Coming"),e("ul",{class:"ac-list"},...i.map(t=>e("li",{class:"ac-soon"},e("strong",null,t.title),e("span",{class:"ac-about"},t.about))))]:[]))}function me(a,t){const o=h.indexOf(t),l=h[o-1],g=h[o+1],r=(s,w,c)=>s?e("a",{href:`${A}/${s.id}`,class:c},w,e("br"),e("strong",null,s.title)):e("span");a.append(e("main",{class:"ac-page"},e("p",null,e("a",{href:A},`← ${n}`)),e("p",{class:"ac-kicker"},`Course ${t.no}`),e("h1",null,t.title),e("p",null,t.about),...t.lessons.flatMap(s=>[e("h2",{id:s.id},s.title),...s.parts.map(ce)]),e("p",{class:"ac-note"},`Try it in Game-Maker: ${t.starters.join(" and ")}, on the Sample CD, show the editor side of these ideas.`),e("nav",{class:"ac-pager","aria-label":"Courses"},r(l,"← Previous","ac-prev"),r(g,"Next →","ac-next"))))}function Ce(a,t){d(a);const o=t?ge(t):void 0;return o?(me(a,o),`${o.title} · ${n}`):(de(a),n)}export{Ce as renderArtCourses};
